import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import {join,resolve} from 'node:path';
import {inventoryFixture,holder,inventoryStep} from './inventory-diagnostic.mjs';import {hash,compact} from './rebalanced.mjs';
export {holder};export const retargetDecision='2deec8acafeb444f258ba2ecdddb2cda65c81db5f1ecba032584348e9479b963';
export const stages=['binding','inventory','claim','snapshot'];
export const failed=()=>({source:'readonly-project-inventory-v1',status:'API_REJECTED',rowCount:0,invalidRows:0,accessors:0,proxies:0,duplicateIds:0,providerIdMissing:0,opaqueIdMissing:0,exactUrlMatches:0,rawValuesRetained:false});
export const verified=()=>({...failed(),status:'VERIFIED',rowCount:2,exactUrlMatches:2});
export async function retargetFixture(){
 const s=await inventoryFixture(),a=holder(s);await assert.rejects(a.withContinuation(async cap=>{await inventoryStep(cap,s,'binding');await inventoryStep(cap,s,'inventory',()=>({source:'readonly-tab-inventory-v1',status:'ORIGINAL_MATCH_COUNT',rowCount:5,invalidRows:0,accessors:0,proxies:0,duplicateIds:0,providerIdMissing:0,originalMatches:0,exactUrlMatches:0,rawValuesRetained:false}));}),/TRIAL_STOPPED/);const drain=await a.stopAndDrain(),j=s.inventory();assert.equal(j.events.length,46);
 const pin=path=>({path,sha256:hash(readFileSync(path))}),canonical={journal:s.path+'.simple-inventory-diagnostic.json',claim:s.path+'.simple-inventory-diagnostic-claim.json',stop:s.path+'.simple-inventory-diagnostic-stop.json',registry:join(s.root,hash(JSON.stringify(s.cfg.epoch))+'.simple-rebalanced.json')},origin={};
 for(const[k,p]of Object.entries(canonical)){const t=join(s.home,'retarget99-origin-'+k+'.json');s.put(t,readFileSync(p));origin[k]=pin(t);}
 const result=join(s.home,'retarget99-result.json');s.put(result,compact({status:'HARD_STOP',failurePhase:'INVENTORY',classification:j.events.at(-1).inventoryClassification,snapshot:null,report:null,drain,trialAccepted:false,completeActualMapProven:false}));origin.result=pin(result);
 const terminal=join(s.home,'retarget99-terminal.json');s.put(terminal,compact({source:'post-return-inventory99-terminal',actualSpent:99,mainSpent:53,uiSpent:46,combinedLimit:232,lifecycle:'HARD_STOP',events:46,allIoSettled:true,pendingNull:true,scopeClosed:true,lockReleased:true,registryClaimStopExact:true,prior97CanonicalUnchanged:true,connection6Bound:true,inventoryApiSucceeded:true,validInventoryRows:5,originalAMatches:0,failureCauseEstablished:'ORIGINAL_A_NOT_IN_FRESH_INVENTORY',tabClosedOrReidentifiedUnknown:true,claimAttempted:false,snapshotAttempted:false,noMutation:true,noRpc:true,noTrialClock:true,trialAccepted:false,retryAuthorized:false,artifacts:Object.values(canonical).map(pin)}));origin.terminal=pin(terminal);
 s.time+=1000;const approval=join(s.home,'retarget99-approval.json');s.put(approval,compact({source:'direct-human-question-reply',questionCall:'synthetic-approval',answer:'同意同專案分頁接續及234上限（建議）',decisionSha256:retargetDecision,recordedAt:s.time,operationBudget:234,retainedSpent:99,selectedBrowserId:j.ownerConnection.selected.browserId,scope:'FOUR_READONLY_STEPS_EXACT_PROJECT_URL_NEW_ENTRY_ONLY',executionStarted:false}));
 s.cfg.readonlyConnection.repair92.diagnostic93.owner94.inventory97.retarget99={decisionHash:retargetDecision,approval:pin(approval),origin};
 for(const f of ['read-authority-project-retarget-budget.py','read-authority-project-selector.mjs','read-authority-project-retarget.mjs']){const p=resolve('scripts',f);s.cfg.sources.push({path:p,sha256:hash(readFileSync(p))});}
 s.cfg.resume={retarget99:true};s.cfg.now=s.time;s.retarget=()=>JSON.parse(readFileSync(s.path+'.simple-project-retarget.json'));s.retained99=Object.fromEntries(Object.values(canonical).filter(p=>p!==canonical.registry).map(p=>[p,readFileSync(p)]));return s;
}
export async function step(cap,s,stage,io=()=>stage==='inventory'?verified():{verified:true}){const r=await cap.inspect(),op={id:'loading-retarget99-n'+(r.connectionUsed+1)+'-'+stage,key:'N:preparation',actor:'publisher',target:'thin-settings',operation:stage==='binding'||stage==='claim'?'claim':stage,units:1,preparation:true};await cap.prepareReadonly({stage:op.id,operations:[op],remainingOrdinaryUi:36});return cap.browserRead(io,op);}
